import {
	getDefaultHexSettings,
	HexMap,
	HexTile,
	LandmassTiles,
	VoronoiValidationSettings,
} from "#base/scripts/hex-map.js";
import { CreateMajorPlayerAreas, PlayerRegion } from "#base/scripts/player-areas.js";
import { profileScope } from "#base/scripts/profiling.js";
import { RandomImpl } from "#base/scripts/random-pcg-32.js";
import {
	ConfigValueRecord,
	ConfigValueType,
	PathKey,
	RegionType,
	RuleConfigValueRecord,
	VariantOverrideType,
} from "#base/scripts/voronoi-types.js";

import { VoronoiBuilder } from "../voronoi-builder.js";
import { LandmassRegion } from "../voronoi-region.js";
import { RegionCell, VoronoiUtils, WrapType } from "../voronoi-utils.js";
import { ContinentGeneratorSettings } from "../voronoi_generators/continent-generator.js";
import { GeneratorType, MapGenerator } from "../voronoi_generators/map-generator.js";

export interface MapSettingConfig {
	label: string;
	description?: string;
	default: number;
	min: number;
	max: number;
	step?: number;
	hidden?: boolean;
}

export type MapGeneratorSettings = ContinentGeneratorSettings;

export interface MapTypeSetting {
	generatorType: GeneratorType;
	filename: string;
	generatorSettings: MapGeneratorSettings;
	mapSettings: Record<string, number>;
}

export type OverrideValueType = [ConfigValueType, VariantOverrideType];
export type VariantValue = OverrideValueType | VariantRecord | VariantRecord[];
export interface VariantRecord {
	[key: string]: VariantValue;
}
interface VariantLeaf {
	path: (string | number)[]; // allow indexes when we go through arrays
	value: OverrideValueType;
}

export interface MapVariantSetting {
	mapSettings: VariantRecord;
	generatorSettings: Record<string, VariantRecord>; // will always be grouped
	ruleSettings: Record<string, Record<string, VariantRecord>>; // will always be group -> rule key -> settings
	hexSettings: VariantRecord;
}

export interface MainSettings {
	mapSettings: ConfigValueRecord;
	generatorSettings: Record<string, ConfigValueRecord>; // will always be grouped
	ruleSettings: Record<string, Record<string, ConfigValueRecord>>; // will always be group -> rule key -> settings
	hexSettings: ConfigValueRecord;
}

export interface MapVariant {
	selected: string | undefined;
	settings: Record<string, MapVariantSetting>;
}
export type MapVariants = Record<string, MapVariant>;

export type MapSettingSchema = Record<string, MapSettingConfig>;

interface VoronoiMapCtor {
	getName(): string;
	new (...args: any[]): VoronoiMap;
}

export interface MapBaseSettings extends ConfigValueRecord {
	totalPlayers: number;
	voronoiCellCountMultiple: number;
	voronoiRelaxationSteps: number;
	wrapX: boolean;
}

export const voronoiMapSchema = {
	totalPlayers: {
		label: "Total Players",
		description: "The number of total players. This value is overridden in-game.",
		default: 8,
		min: 1,
		max: 24,
		step: 1,
	},
	voronoiCellCountMultiple: {
		label: "Cell Count Multiple",
		description: "The number of voronoi cells to use relative to hexes.",
		default: 1,
		min: 0.5,
		max: 4.0,
		step: 0.1,
	},
	voronoiRelaxationSteps: {
		label: "Cell Relaxation Steps",
		description: "The number times to relax the voronoi diagram from its original random positions.",
		default: 3,
		min: 0,
		max: 10,
		step: 1,
	},
	wrapX: {
		label: "Wrap Meridian",
		description: "Wrap the map around the meridian.",
		default: 0,
		min: 0,
		max: 1,
		step: 1,
	},
} satisfies MapSettingSchema;

export abstract class VoronoiMap<T extends MapBaseSettings = MapBaseSettings> {
	protected m_baseSchema: MapSettingSchema & { [K in keyof MapBaseSettings]: MapSettingConfig };

	protected m_builder: VoronoiBuilder = new VoronoiBuilder();
	protected m_initialized = false;
	protected m_settings: T;
	protected m_variants: MapVariants = {};
	protected m_defaultSettings: MainSettings = {
		mapSettings: {},
		generatorSettings: {},
		ruleSettings: {},
		hexSettings: {},
	}; // not altered after construction
	protected m_defaultJson: object = {}; // default json object optionally passed in.
	protected m_primarySettings: MainSettings = {
		mapSettings: {},
		generatorSettings: {},
		ruleSettings: {},
		hexSettings: {},
	};
	protected m_builderNeedsInit = true;

	protected m_hexDims: float2 = { x: 0, y: 0 };
	protected m_generator: MapGenerator;
	protected m_hexTiles: HexMap;

	private m_rndInitState: RandomImpl.RandomState | undefined;
	private m_rndSimulateInternalState: RandomImpl.RandomState | undefined;
	private m_rndSimulateState: RandomImpl.RandomState | undefined;
	private m_initialVariants: Record<string, string> = {};
	private m_dominantCells: RegionCell[][] = []; // maps x/y hex tiles to the region cell used for that tile, saved during hex tile initialization for use in later processing if needed.

	abstract init(mapSize: float2): void;
	abstract getFilename(): string;
	protected abstract simulateInternal(): void;

	constructor(
		baseSchema: typeof voronoiMapSchema,
		generator: MapGenerator,
		defaultGeneratorSettings: ConfigValueRecord,
		defaultRulesSettings: RuleConfigValueRecord,
		defaultJson: object = {},
	) {
		this.m_baseSchema = baseSchema;
		this.m_settings = this.m_primarySettings.mapSettings as T;
		this.m_generator = generator;
		this.m_defaultJson = defaultJson;
		this.m_hexTiles = new HexMap();

		for (const [key, value] of Object.entries(this.getSettingsConfig())) {
			this.m_defaultSettings.mapSettings[key] = value.default;
		}
		this.m_defaultSettings.generatorSettings = VoronoiUtils.clone(defaultGeneratorSettings) as any;
		this.m_defaultSettings.ruleSettings = VoronoiUtils.clone(defaultRulesSettings) as any;
		this.m_defaultSettings.hexSettings = getDefaultHexSettings();

		this.m_primarySettings = VoronoiUtils.clone(this.m_defaultSettings);
		this.resetToDefault();
	}

	getSettings(): T {
		return this.m_settings;
	}
	setSettings(settings: T): void {
		this.m_settings = { ...settings };
	}

	getHexTiles() {
		return this.m_hexTiles;
	}

	getGenerator() {
		return this.m_generator;
	}

	getSettingsConfig(): MapSettingSchema {
		return this.m_baseSchema;
	}

	getWrapType(): WrapType {
		return this.getSettings().wrapX ? WrapType.WrapX : WrapType.None;
	}

	createMajorPlayerAreas(
		valueFunction?: (tile: HexTile) => number,
		playerRegions: PlayerRegion[] | undefined = undefined,
	) {
		if (playerRegions == undefined) {
			// Assign players based on the total player count and the sizes of the player landmasses (coasts count as 0.5 tiles).
			playerRegions = [];
			const totalPlayers = this.getSettings().totalPlayers;
			const mapStats = this.getHexTiles().getMapStats();

			const scoreLandmass = (landmass: LandmassTiles) => landmass.land + landmass.coast * 0.5;
			const totalPlayerLandScore = mapStats.playerLandmasses.reduce(
				(sum, landmass) => sum + scoreLandmass(landmass),
				0,
			);

			let playersAllocated = 0;
			const remainders: { id: number; remainder: number }[] = [];
			for (const playerLandmass of mapStats.playerLandmasses) {
				const playerRegion = new PlayerRegion();
				playerRegions.push(playerRegion);
				playerRegion.id = playerLandmass.playerLandmassId;
				playerRegion.filter = (tile: HexTile) => tile.playerLandmassId == playerLandmass.playerLandmassId;

				const rawScore = (scoreLandmass(playerLandmass) / totalPlayerLandScore) * totalPlayers;
				playerRegion.playerAreas = Math.floor(rawScore);
				remainders.push({ id: remainders.length, remainder: rawScore - playerRegion.playerAreas });

				playersAllocated += playerRegion.playerAreas;
			}

			remainders.sort((a, b) => b.remainder - a.remainder);
			for (const remainder of remainders) {
				if (playersAllocated >= totalPlayers) break;
				playerRegions[remainder.id].playerAreas++;
				playersAllocated++;
			}
		}

		CreateMajorPlayerAreas(this.m_hexTiles, playerRegions, valueFunction, {
			wrap: this.getWrapType(),
			width: this.m_hexDims.x,
			height: this.m_hexDims.y,
		});
	}

	public simulate() {
		const perfScope: profileScope = new profileScope("Simulating Voronoi Map.");
		if (this.m_rndSimulateInternalState == undefined) {
			this.m_rndSimulateInternalState = RandomImpl.getState();
		}
		RandomImpl.setState(this.m_rndSimulateInternalState);

		this.applyVariants();
		this.simulateInternal();
		this.m_generator.logSettings();

		this.initBuilder();

		if (this.m_rndSimulateState == undefined) {
			this.m_rndSimulateState = RandomImpl.getState();
		}
		RandomImpl.setState(this.m_rndSimulateState);

		this.m_dominantCells = [];

		this.m_generator.simulate();
		this.m_hexTiles.initFromRegionCells(
			this.m_hexDims.x,
			this.m_hexDims.y,
			this.m_generator.getKdTree(),
			this.m_generator.getLandmasses(),
			(cell: RegionCell) => this.getPlayerLandmassFromCell(cell),
			this.getVoronoiValidationSettings(),
			this.m_dominantCells,
		);
		this.m_hexTiles.validate();
		perfScope.end();
	}

	// Default expects oceans to be 0, player landmasses to be 1-n, and non-player land to be > n.
	protected getPlayerLandmassFromCell(cell: RegionCell): number {
		if (cell.landmassId > 0) {
			const landmass: LandmassRegion = this.m_generator.getLandmasses()[cell.landmassId];
			if (landmass.type === RegionType.Island) {
				return 0;
			} else {
				return cell.landmassId;
			}
		}
		return -1;
	}

	getRegionCellForHex(x: number, y: number): RegionCell | undefined {
		return this.m_dominantCells[x]?.[y];
	}

	protected getVoronoiValidationSettings() {
		return new VoronoiValidationSettings();
	}

	initInternal(hexDims: float2) {
		this.m_hexDims = hexDims;
		this.m_rndSimulateState = undefined;
		this.m_rndSimulateInternalState = undefined;
		this.m_rndInitState = undefined;
		this.m_builderNeedsInit = true;

		// Apply any variants that were set before initialization.
		if (!this.m_initialized) {
			for (const [variantName, key] of Object.entries(this.m_initialVariants)) {
				if (variantName in this.m_variants && key in this.m_variants[variantName].settings) {
					const variant = this.m_variants[variantName];
					variant.selected = key;
				}
			}
			this.m_initialized = true;
		}

		this.applyVariants();
	}

	initBuilder() {
		if (this.m_builderNeedsInit) {
			if (this.m_rndInitState == undefined) {
				this.m_rndInitState = RandomImpl.getState();
			}
			RandomImpl.setState(this.m_rndInitState);
			const wrapType: WrapType = this.getSettings().wrapX ? WrapType.WrapX : WrapType.None;
			this.m_builder.init(
				this.m_hexDims,
				this.getSettings().voronoiCellCountMultiple,
				this.getSettings().voronoiRelaxationSteps,
				wrapType,
			);
			this.m_generator.init(
				this.m_builder.getDiagramDims(),
				this.m_builder.getDiagram(),
				this.m_hexDims,
				wrapType,
			);
			this.m_builderNeedsInit = false;
		}
	}

	resetToDefault() {
		this.m_primarySettings = VoronoiUtils.clone(this.m_defaultSettings);
		if (this.m_defaultJson) {
			this.loadSettingsFromJson(this.m_defaultJson);
		}
	}

	setPrimaryMapSetting(keyPath: PathKey[], value: ConfigValueType) {
		VoronoiUtils.setPath(this.m_primarySettings.mapSettings, keyPath, value);
		if (
			["voronoiCellCountMultiple", "voronoiRelaxationSteps", "wrapX"].includes(
				String(keyPath[keyPath.length - 1]),
			)
		) {
			this.m_builderNeedsInit = true;
		}
	}

	setPrimaryGeneratorSetting(keyPath: PathKey[], value: ConfigValueType) {
		VoronoiUtils.setPath(this.m_primarySettings.generatorSettings, keyPath, value);
	}

	setPrimaryRuleSetting(keyPath: PathKey[], value: ConfigValueType) {
		VoronoiUtils.setPath(this.m_primarySettings.ruleSettings, keyPath, value);
	}

	setPrimaryHexSetting(keyPath: PathKey[], value: ConfigValueType) {
		VoronoiUtils.setPath(this.m_primarySettings.hexSettings, keyPath, value);
	}

	getPrimaryMapSetting(keyPath: PathKey[]): ConfigValueType {
		return VoronoiUtils.getPath(this.m_primarySettings.mapSettings, keyPath);
	}

	getPrimaryGeneratorSetting(keyPath: PathKey[]): ConfigValueType {
		return VoronoiUtils.getPath(this.m_primarySettings.generatorSettings, keyPath);
	}

	getPrimaryRuleSetting(keyPath: PathKey[]): ConfigValueType {
		return VoronoiUtils.getPath(this.m_primarySettings.ruleSettings, keyPath);
	}

	getPrimaryHexSetting(keyPath: PathKey[]): ConfigValueType {
		return VoronoiUtils.getPath(this.m_primarySettings.hexSettings, keyPath);
	}

	getVariants(): MapVariants {
		return this.m_variants;
	}

	setVariants(variants: MapVariants) {
		this.m_variants = variants;
		this.m_builderNeedsInit = true;
	}

	createVariant(name: string) {
		this.m_variants[name] = { selected: undefined, settings: {} };
	}

	deleteVariant(name: string) {
		if (name in this.m_variants) {
			delete this.m_variants[name];
			this.m_builderNeedsInit = true;
		}
	}

	createVariantKey(variantName: string, key: string) {
		if (variantName in this.m_variants) {
			this.m_variants[variantName].settings[key] = {
				generatorSettings: {},
				mapSettings: {},
				ruleSettings: {},
				hexSettings: {},
			};
			this.m_builderNeedsInit = true;
		}
	}

	deleteVariantKey(variantName: string, key: string) {
		if (variantName in this.m_variants && key in this.m_variants[variantName].settings) {
			delete this.m_variants[variantName].settings[key];
			this.m_builderNeedsInit = true;
		}
	}

	setSelectedVariantKey(variantName: string, key: string | undefined) {
		if (!this.m_initialized) {
			if (key === undefined) {
				if (variantName in Object.keys(this.m_initialVariants)) {
					delete this.m_initialVariants[variantName];
				}
			} else {
				this.m_initialVariants[variantName] = key;
			}
		} else if (variantName in this.m_variants && (!key || key in this.m_variants[variantName].settings)) {
			const variant = this.m_variants[variantName];
			variant.selected = key;
			this.m_builderNeedsInit = true;
		}
	}

	applyOverrideAtPath(
		target: unknown,
		path: Readonly<string | number>[],
		[overrideValue, overrideType]: OverrideValueType,
	) {
		switch (overrideType) {
			case VariantOverrideType.Replace:
				VoronoiUtils.setPath(target, path, overrideValue, false);
				break;
			case VariantOverrideType.Add: {
				const existingValue = VoronoiUtils.getPath(target, path);
				VoronoiUtils.setPath(target, path, existingValue + Number(overrideValue), false);
				break;
			}
			case VariantOverrideType.Multiply: {
				const existingValue = VoronoiUtils.getPath(target, path);
				VoronoiUtils.setPath(target, path, existingValue * Number(overrideValue), false);
				break;
			}
		}
	}

	applyVariants() {
		// First apply the primary settings
		this.setSettings(VoronoiUtils.clone(this.m_primarySettings.mapSettings) as T);
		this.getGenerator().setSettings(VoronoiUtils.clone(this.m_primarySettings.generatorSettings));
		this.getHexTiles().setSettings(VoronoiUtils.clone(this.m_primarySettings.hexSettings));

		for (const [groupKey, rules] of Object.entries(this.getGenerator().getRules())) {
			for (const [ruleName, rule] of Object.entries(rules)) {
				const primarySettings = this.m_primarySettings.ruleSettings[groupKey][ruleName];
				const { weight, isActive, ...config } = primarySettings;
				rule.weight = Number(weight);
				rule.isActive = Boolean(isActive);
				rule.configValues = config as ConfigValueRecord;
			}
		}

		// Apply active variants on top.
		for (const variant of Object.values(this.m_variants)) {
			if (variant.selected == undefined) continue;
			const selected = variant.settings[variant.selected];

			for (const { path, value } of this.iterateVariantLeaves(selected.mapSettings)) {
				this.applyOverrideAtPath(this.getSettings(), path, value);
			}

			for (const { path, value } of this.iterateVariantLeaves(selected.generatorSettings)) {
				this.applyOverrideAtPath(this.getGenerator().getSettings(), path, value);
			}

			for (const { path, value } of this.iterateVariantLeaves(selected.hexSettings)) {
				this.applyOverrideAtPath(this.getHexTiles().getSettings(), path, value);
			}

			const rules = this.getGenerator().getRules();
			for (const { path, value } of this.iterateVariantLeaves(selected.ruleSettings)) {
				const rule = rules[path[0]][path[1]];
				const ruleProp = path[2];
				if (ruleProp == "weight") {
					rule.weight = Number(value);
				} else if (ruleProp == "isActive") {
					rule.isActive = Boolean(value);
				} else {
					this.applyOverrideAtPath(rule?.configValues, path.slice(2), value);
				}
			}
		}
	}

	getSelectedVariantKey(variantName: string): string | undefined {
		if (variantName in this.m_variants) {
			return this.m_variants[variantName].selected;
		}
		return undefined;
	}

	setVariantMapSetting(name: string, key: string, path: string[], value: OverrideValueType) {
		this.setVariantSettingInternal(name, key, "mapSettings", path, value);
		if (["voronoiCellCountMultiple", "voronoiRelaxationSteps", "wrapX"].includes(String(path[path.length - 1]))) {
			this.m_builderNeedsInit = true;
		}
	}

	setVariantGeneratorSetting(name: string, key: string, path: string[], value: OverrideValueType) {
		this.setVariantSettingInternal(name, key, "generatorSettings", path, value);
	}

	setVariantRuleSetting(name: string, key: string, path: string[], value: OverrideValueType) {
		this.setVariantSettingInternal(name, key, "ruleSettings", path, value);
	}

	setVariantHexSetting(name: string, key: string, path: string[], value: OverrideValueType) {
		this.setVariantSettingInternal(name, key, "hexSettings", path, value);
	}

	getVariantMapSetting(name: string, key: string, path: string[]): OverrideValueType | undefined {
		return this.getVariantSettingInternal(name, key, "mapSettings", path);
	}

	getVariantGeneratorSetting(name: string, key: string, path: string[]): OverrideValueType | undefined {
		return this.getVariantSettingInternal(name, key, "generatorSettings", path);
	}

	getVariantRuleSetting(name: string, key: string, path: string[]): OverrideValueType | undefined {
		return this.getVariantSettingInternal(name, key, "ruleSettings", path);
	}

	getVariantHexSetting(name: string, key: string, path: string[]): OverrideValueType | undefined {
		return this.getVariantSettingInternal(name, key, "hexSettings", path);
	}

	deleteVariantMapSetting(name: string, key: string, path: string[]) {
		this.deleteVariantSettingInternal(name, key, "mapSettings", path);
		if (["voronoiCellCountMultiple", "voronoiRelaxationSteps", "wrapX"].includes(String(path[path.length - 1]))) {
			this.m_builderNeedsInit = true;
		}
	}

	deleteVariantGeneratorSetting(name: string, key: string, path: string[]) {
		this.deleteVariantSettingInternal(name, key, "generatorSettings", path);
	}

	deleteVariantRuleSetting(name: string, key: string, path: string[]) {
		this.deleteVariantSettingInternal(name, key, "ruleSettings", path);
	}

	deleteVariantHexSetting(name: string, key: string, path: string[]) {
		this.deleteVariantSettingInternal(name, key, "hexSettings", path);
	}

	getMapVariantsForPath(path: string[]) {
		return this.getVariantsForPath(path, "mapSettings");
	}

	getGeneratorVariantsForPath(path: string[]) {
		return this.getVariantsForPath(path, "generatorSettings");
	}

	getRuleVariantsForPath(path: string[]) {
		return this.getVariantsForPath(path, "ruleSettings");
	}

	getHexVariantsForPath(path: string[]) {
		return this.getVariantsForPath(path, "hexSettings");
	}

	protected getVariantsForPath(path: string[], recordName: keyof MapVariantSetting) {
		const variants: { name: string; setting: string }[] = [];
		for (const [variantName, variant] of Object.entries(this.m_variants)) {
			for (const settingName of Object.keys(variant.settings)) {
				if (this.getVariantSettingInternal(variantName, settingName, recordName, path) != undefined) {
					variants.push({ name: variantName, setting: settingName });
				}
			}
		}
		return variants;
	}

	getName(): string {
		// Force sub classes to have a static getName(), and provide an instance getName() at the same time.
		const ctor = this.constructor as VoronoiMapCtor;
		return ctor.getName();
	}

	protected setVariantSettingInternal(
		variantName: string,
		variantKey: string,
		recordName: keyof MapVariantSetting,
		path: string[],
		value: OverrideValueType,
	) {
		if (variantName in this.m_variants && variantKey in this.m_variants[variantName].settings) {
			const variant = this.m_variants[variantName];
			const settings = variant.settings[variantKey];
			if (settings[recordName] == undefined) {
				settings[recordName] = {};
			}

			const setRecursive = (record: VariantRecord | VariantRecord[], depth: number): void => {
				const item = path[depth];
				const nextDepth = depth + 1;
				const isLast = nextDepth == path.length;
				if (Array.isArray(record)) {
					if (item == "") {
						if (isLast) {
							return; // Error - cannot set a value on an array.
						} else {
							for (const element of record) {
								setRecursive(element, nextDepth);
							}
						}
					} else if (VoronoiUtils.isArrayIndexKey(item)) {
						if (Number(item) < record.length) {
							setRecursive(record[Number(item)], nextDepth);
						} else {
							return; // Error - out of array bounds.
						}
					} else {
						return; // Error - trying to set a string key on an array.
					}
				} else if (isLast) {
					record[item] = value;
				} else {
					if (record[item] == undefined) {
						const nextItem = path[nextDepth];
						if (nextItem == "" || VoronoiUtils.isArrayIndexKey(nextItem)) {
							const existing = VoronoiUtils.getPath(
								this.m_primarySettings[recordName],
								path.slice(0, nextDepth),
							);
							if (Array.isArray(existing)) {
								record[item] = new Array<VariantRecord>(existing.length).fill({});
								if (nextItem == "") {
									for (const element of record[item]) {
										setRecursive(element, nextDepth + 1);
									}
									return;
								}
							}
						} else {
							record[item] = {};
						}
					}
					setRecursive(record[item] as VariantRecord, nextDepth);
				}
			};
			setRecursive(settings[recordName], 0);

			if (variant.selected === variantKey) {
				//this.applyVariants();
			}
		}
	}

	protected getVariantSettingInternal(
		variantName: string,
		variantKey: string,
		recordName: keyof MapVariantSetting,
		path: string[],
	): OverrideValueType | undefined {
		if (variantName in this.m_variants && variantKey in this.m_variants[variantName].settings) {
			let record: VariantRecord | VariantRecord[] = this.m_variants[variantName].settings[variantKey][recordName];
			for (let i = 0; i < path.length; ++i) {
				const item = path[i];
				if (!record) break;
				if (Array.isArray(record)) {
					if (item == "") {
						record = record[0]; // Assume first item in array
					} else if (VoronoiUtils.isArrayIndexKey(item)) {
						record = record[Number(item)];
					} else {
						return undefined;
					}
				} else if (i == path.length - 1) {
					return record[item] as OverrideValueType;
				} else {
					record = record[item] as VariantRecord;
				}
			}
		}
		return undefined;
	}

	protected deleteVariantSettingInternal(
		variantName: string,
		variantKey: string,
		recordName: keyof MapVariantSetting,
		path: string[],
	) {
		if (variantName in this.m_variants && variantKey in this.m_variants[variantName].settings) {
			const deleteRecursive = (record: VariantRecord | VariantRecord[], depth: number) => {
				const item = path[depth];
				const isLast = depth == path.length - 1;
				const nextDepth = depth + 1;
				if (Array.isArray(record)) {
					if (item == "") {
						if (isLast) {
							record.length = 0;
						} else {
							for (const element of record) {
								deleteRecursive(element, nextDepth);
							}
						}
					} else if (VoronoiUtils.isArrayIndexKey(item)) {
						const idx = Number(item);
						const element = record[idx];
						if (!element) return; // out of range / missing
						deleteRecursive(record[Number(item)], nextDepth);
					} else {
						// Error, trying to delete string key from array.
						return;
					}
				} else if (isLast) {
					delete record[item];
				} else {
					const child = record[item];
					if (child === undefined) return; // not found
					deleteRecursive(child as VariantRecord, nextDepth);
				}
			};
			deleteRecursive(this.m_variants[variantName].settings[variantKey][recordName], 0);

			if (this.m_variants[variantName].selected === variantKey) {
				//this.applyVariants();
			}
		}
	}

	public loadSettingsFromJson(json: string | object) {
		this.m_primarySettings = VoronoiUtils.clone(this.m_defaultSettings);
		const configObject = typeof json === "string" ? JSON.parse(json) : json;

		VoronoiUtils.deepMerge(this.m_primarySettings.mapSettings, configObject.mapConfig);
		VoronoiUtils.deepMerge(this.m_primarySettings.generatorSettings, configObject.generatorConfig);

		const rulesConfig = VoronoiUtils.explodeConfig(configObject.rulesConfig) as any;
		VoronoiUtils.deepMerge(this.m_primarySettings.ruleSettings, rulesConfig);

		if (configObject.hexConfig) {
			VoronoiUtils.deepMerge(this.m_primarySettings.hexSettings, configObject.hexConfig);
		}

		if (configObject.variantSettings) {
			this.setVariants(configObject.variantSettings);
		}
	}

	public loadSettingsFromJs(jsText: string) {
		const match = jsText.match(/export\s+default\s+({[\s\S]*});?\s*$/);
		if (!match) throw new Error("Could not find export default object");
		return this.loadSettingsFromJson(match[1]);
	}

	private static isOverrideValue(v: VariantValue): v is OverrideValueType {
		return (
			Array.isArray(v) &&
			v.length === 2 &&
			(typeof v[0] === "number" || typeof v[0] === "boolean") &&
			typeof v[1] === "number"
		);
	}

	private static isVariantRecord(v: VariantValue): v is VariantRecord {
		return typeof v === "object" && v !== null && !Array.isArray(v);
	}

	private static isVariantRecordArray(v: VariantValue): v is VariantRecord[] {
		return Array.isArray(v) && !VoronoiMap.isOverrideValue(v);
	}

	private *iterateVariantLeaves(root: VariantRecord): Generator<VariantLeaf> {
		if (root == undefined) return;

		function* walkValue(value: VariantValue, prefix: (string | number)[]): Generator<VariantLeaf> {
			if (VoronoiMap.isOverrideValue(value)) {
				yield { path: prefix, value };
			} else if (VoronoiMap.isVariantRecord(value)) {
				yield* walkObject(value, prefix);
			} else if (VoronoiMap.isVariantRecordArray(value)) {
				for (let i = 0; i < value.length; ++i) {
					yield* walkObject(value[i], [...prefix, i]);
				}
			}
		}

		function* walkObject(node: VariantRecord, prefix: (string | number)[]): Generator<VariantLeaf> {
			for (const [key, child] of Object.entries(node) as [string, VariantValue][]) {
				yield* walkValue(child, [...prefix, key]);
			}
		}

		yield* walkObject(root, []);
	}
}
